package commands_test

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/hanagantig/goro/internal/commands"
	"github.com/hanagantig/goro/internal/config"
)

// oldMarker is the header internal/app files had before ADR 0001; it still counts as the marker.
const oldMarker = "// Code generated by goro; DO NOT EDIT."

// withOldMarker swaps the marker line of a generated file for the old header.
func withOldMarker(t *testing.T, content string) string {
	t.Helper()

	lines := strings.Split(content, "\n")
	for i, line := range lines {
		if markerLine.MatchString(line) {
			lines[i] = oldMarker
			return strings.Join(lines, "\n")
		}
	}
	t.Fatalf("no marker line in:\n%s", content)

	return ""
}

func TestInitAcceptsDirWithOnlyGoroYaml(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "goro.yaml")
	if err := os.WriteFile(path, []byte(baseConfig), 0o644); err != nil {
		t.Fatal(err)
	}
	cfg, err := config.NewConfig(path)
	if err != nil {
		t.Fatalf("load config: %v", err)
	}
	cfg.App.WorkDir = dir

	if err := commands.Init(cfg, commands.Options{SkipGoMod: true}); err != nil {
		t.Fatalf("init in a dir that holds only goro.yaml: %v", err)
	}

	// baseConfig has no work_dir, which LoadConfig would ask for. init writes the answer into the
	// project's goro.yaml as work_dir: . (ADR 0002) and leaves every other byte as it was.
	want := strings.Replace(baseConfig, "  module: demo\n", "  module: demo\n  work_dir: .\n", 1)
	if got := readFile(t, dir, "goro.yaml"); got != want {
		t.Errorf("goro.yaml after init:\n%s\nwant the original with only a work_dir: . line inserted:\n%s", got, want)
	}
	if !exists(dir, "internal/app/app.go") || !hasMarker(readFile(t, dir, "internal/app/app.go")) {
		t.Errorf("init didn't generate internal/app/app.go with the marker")
	}
}

func TestInitRefusesProjectWithOldMarker(t *testing.T) {
	dir := t.TempDir()
	initProject(t, newConfig(t, dir))

	// A project made by an older goro: internal/app files carry the old header.
	for _, path := range []string{"internal/app/app.go", "internal/app/container.go", "internal/app/database.go", "internal/app/http.go", "internal/app/logger.go"} {
		writeFile(t, dir, path, withOldMarker(t, readFile(t, dir, path)))
	}

	err := commands.Init(newConfig(t, dir), commands.Options{SkipGoMod: true})
	if !errors.Is(err, commands.ErrProjectExists) {
		t.Errorf("init error = %v, want ErrProjectExists for a project with the old marker", err)
	}
}

func TestUpdateRegeneratesFileWithOldMarker(t *testing.T) {
	dir := t.TempDir()
	initProject(t, newConfig(t, dir))

	const path = "internal/app/container.go"
	fresh := readFile(t, dir, path)
	writeFile(t, dir, path, withOldMarker(t, fresh))

	report := update(t, newConfig(t, dir))

	assertAction(t, report, path, commands.ActionOverwrite)
	if readFile(t, dir, path) != fresh {
		t.Errorf("update didn't regenerate %s, which carries the old marker", path)
	}
}
